#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。

用法:
    python3 count_nonempty.py data.csv
"""

import argparse
import csv
from collections import Counter


def count_nonempty(path):
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return [], Counter()

        counts = Counter()
        for row in reader:
            for i, value in enumerate(row):
                if value.strip():
                    counts[i] += 1

        names = header + [f"column_{i + 1}" for i in range(len(header), max(counts, default=-1) + 1)]
        return names, counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("file", help="CSV 文件路径")
    args = parser.parse_args()

    names, counts = count_nonempty(args.file)
    if not names:
        print("文件为空")
        return

    width = max(len(name) for name in names)
    for i, name in enumerate(names):
        print(f"{name:<{width}}  {counts[i]}")


if __name__ == "__main__":
    main()
